const b=$input.first().json.body??{};
if(b.agentKey!=='ancfz'||b.otpVerified!==true||b.customerConsent!==true)throw new Error('OTP/consent required from Node');
if(!Number.isSafeInteger(b.amount)||b.amount<=0||b.amount>10000000)throw new Error('Invalid amount; template expects integer currency units');
if(typeof b.currency!=='string'||!/^[A-Z]{3}$/.test(b.currency))throw new Error('Invalid currency');
if(typeof b.ticketId!=='string'||!/^[0-9a-f-]{36}$/i.test(b.ticketId))throw new Error('Invalid ticket');
if(typeof b.quotationId!=='string'||b.quotationId.length>128)throw new Error('Invalid quote');
return [{json:{ticketId:b.ticketId,quotationId:b.quotationId,amount:b.amount,currency:b.currency}}];

const r=$input.first().json;const id=r.payment_id??r.paymentId??r.id;const url=r.payment_url??r.paymentUrl??r.checkout_url;
if(typeof id!=='string'||id.length<2||id.length>200||typeof url!=='string')throw new Error('Gateway response missing ID or checkout URL');
let u;try{u=new URL(url);}catch{throw new Error('Invalid checkout URL');}
if(u.protocol!=='https:'||u.hostname!=='mockgateway.com')throw new Error('Unexpected checkout URL host');
const expected=$('Validate Authorized Payment').first().json;
return [{json:{status:'link_created',provider:'mockgateway_sandbox',paymentId:id,paymentUrl:url,ticketId:expected.ticketId,quotationId:expected.quotationId,amount:expected.amount,currency:expected.currency}}];
